scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0

    # Count all pairs where an earlier entry exceeds a later entry
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.linear_congruential:
def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    for _ in range(k):
        x = ((a * x) + b) % m

    return float(x)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.sum_floor_division:
def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']

    total = 0
    for i in range(len(a)):
        total += a[i] // b[i]

    return float(total)

